package com.wheelwright.evidence.v2.portfolio;

import com.fasterxml.jackson.databind.node.*;
import com.wheelwright.evidence.v2.PositionSnapshot;
import java.sql.Connection;
import java.time.Instant;
import java.util.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioJson.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioRepository.*;

/** Reconciles observed current inventory, never opening/closing events or governed occurrence continuity. */
public final class PortfolioCurrentExposure {
 private final PortfolioRepository repo;
 public PortfolioCurrentExposure(PortfolioRepository repo){this.repo=repo;}
 public void reconcile(Connection tx,String account,Map<String,Map<String,ObjectNode>> fresh,Instant now)throws Exception{
  var selected=new PortfolioSnapshots(repo).current(account);if(selected.isEmpty())return;var cut=selected.get();
  var positions=repo.list(tx,Kind.POSITION,Set.of(account)).stream().filter(p->!p.value().path("state").asText().equals("CLOSED")&&!p.value().at("/exposure/status").asText().equals("SUPERSEDED_INTERPRETATION")).toList();
  var scopes=new LinkedHashMap<String,Set<String>>();var demand=new HashMap<String,Integer>();
  for(var p:positions){var keys=scope(tx,p);scopes.put(p.uri(),keys);for(String key:keys)demand.merge(key,1,Integer::sum);}
  var current=new LinkedHashMap<String,ObjectNode>();if(fresh.containsKey(cut.snapshotId()))current.putAll(fresh.get(cut.snapshotId()));
  for(var p:positions)if(Objects.equals(p.snapshot(),cut.snapshotId()))for(var leaf:leaves(repo.get(tx,p.value().at("/currentConstruction/href").asText()).orElseThrow().value().path("composition")))current.putIfAbsent(leaf.at("/allocation/inventory/key").asText(),leaf);
  var holdings=repo.list(tx,Kind.HOLDING,Set.of(account)).stream().filter(h->Objects.equals(h.snapshot(),cut.snapshotId())).toList();
  boolean securitiesComplete=securitiesComplete(tx,cut);
  for(var p:positions){
   if(p.value().at("/exposure/sourceSnapshotId").asText().equals(cut.snapshotId()))continue;
   if(Objects.equals(p.snapshot(),cut.snapshotId())){var value=p.value().deepCopy();value.set("exposure",exposure(cut,"OBSERVED",evidence(current.values()),"Current observed constituent quantities; economic occurrence continuity remains unproven."));repo.put(tx,new Document(Kind.POSITION,p.uri(),account,value,p.snapshot(),p.sourceKey()));continue;}
   var keys=scopes.get(p.uri());var next=new ArrayList<ObjectNode>();boolean ambiguous=keys.isEmpty()||keys.stream().anyMatch(k->demand.getOrDefault(k,0)!=1);
   for(String key:keys)if(current.containsKey(key))next.add(current.get(key).deepCopy());
   boolean hasCash=keys.stream().anyMatch(k->holdings.stream().anyMatch(h->Objects.equals(h.sourceKey(),k)&&h.value().path("kind").asText().equals("CASH")))||historicalLeaves(tx,p).stream().anyMatch(n->n.path("kind").asText().equals("CASH"));
   boolean complete=hasCash?cut.cashObservation()!=null&&cut.cashObservation().status().equals("OBSERVED")||cut.observation()==null&&cut.excludedNonPositionRows()==0:securitiesComplete;
   boolean explicitZero=!keys.isEmpty()&&keys.stream().allMatch(k->holdings.stream().anyMatch(h->Objects.equals(h.sourceKey(),k)&&number(h.value().path("quantity"))!=null&&number(h.value().path("quantity")).signum()==0));
   String status=ambiguous?"UNKNOWN":!complete&&!explicitZero?"RETAINED":next.isEmpty()?"ZERO_OBSERVED":"OBSERVED";
   var value=p.value().deepCopy();var old=repo.get(tx,value.at("/currentConstruction/href").asText()).orElseThrow();
   if(!status.equals("RETAINED")){
    var c=old.value().deepCopy();String id=UUID.randomUUID().toString(),uri="/v2/constructions/"+id;c.put("id",id).put("createdAt",now.toString()).put("changeKind","EVIDENCE_REINTERPRETATION").put("predecessorStatus","KNOWN");c.set("self",link(uri));c.set("predecessor",link(old.uri()));var composition=obj().put("kind","GROUP").put("nodeId","ROOT").putNull("modelVersion");var members=array();if(!ambiguous)next.forEach(members::add);composition.set("children",members);c.set("composition",composition);c.set("relationships",array());var es=evidence(ambiguous?List.of():next);c.set("evidence",es);var recognition=obj().put("status","UNCLASSIFIED").putNull("modelVersion");recognition.set("candidateModels",array());recognition.set("reasonCodes",array().add("ASSOCIATION_UNRESOLVED"));recognition.set("evidence",es);recognition.set("authority",PortfolioSources.authority(account,id,"BROKER_HOLDING_OBSERVATION",ambiguous?"UNRESOLVED":"QUALIFIED",es,List.of(uri),"Current custody interpretation only; no split/recombine, opening, closing or uninterrupted occurrence asserted."));c.set("recognition",recognition);c.set("warnings",array().add(warning("ASSOCIATION_UNRESOLVED","/composition","Retained predecessor and independently readable custody remain inspectable.",ambiguous?"Competing Position inventory scopes prevent a unique current allocation; empty composition means unknown exposure, not zero or closure.":"Quantities reflect the applicable source cut. Observed disappearance or reduction is not a proven closing event.")));repo.put(tx,new Document(Kind.CONSTRUCTION,uri,account,c,cut.snapshotId(),p.sourceKey()));value.set("currentConstruction",link(uri));var evaluated=PortfolioMath.evaluate(c,Map.of(),now);for(String retained:List.of("economicComparison","historicalMarketValue"))if(value.at("/evaluation/"+retained).isObject())evaluated.set(retained,value.at("/evaluation/"+retained).deepCopy());value.set("evaluation",evaluated);
   }
   var es=evidence(next);if(es.isEmpty())for(var h:holdings)for(var e:h.value().path("evidence"))es.add(e.deepCopy());if(!status.equals("OBSERVED")&&value.path("state").asText().equals("OPEN")){value.put("state","UNRESOLVED");var state=(ObjectNode)value.path("stateEvidence");state.put("status","UNRESOLVED").put("completeness","UNKNOWN").putNull("establishedAt");state.set("evidence",es.deepCopy());}value.set("exposure",exposure(cut,status,es,"Observed inventory is separate from lifecycle state. No closing event, uninterrupted occurrence, original basis or reopening is inferred."));((ObjectNode)value.path("allocation")).put("status","UNKNOWN");((ArrayNode)value.path("warnings")).add(warning("HOLDING_RECONCILIATION_CONFLICT","/exposure","Historical observations and lifecycle evidence remain inspectable.",status.equals("RETAINED")?"Incomplete source coverage cannot renew or erase the prior exposure; current financial totals are unavailable.":status.equals("UNKNOWN")?"Current allocation is ambiguous; inspect broker holdings independently. No old quantity is asserted as current.":"Current constituent observation changed; lifecycle occurrence and event associations remain unresolved."));PortfolioSources.qualify(value);repo.put(tx,new Document(Kind.POSITION,p.uri(),account,value,cut.snapshotId(),p.sourceKey()));
  }
 }
 private static boolean securitiesComplete(Connection tx,PositionSnapshot cut)throws Exception{
  if(cut.observation()!=null)return true;if(cut.artifactId()==null)return cut.excludedNonPositionRows()==0;
  try(var q=tx.prepareStatement("SELECT payload FROM brokerage_artifact WHERE account=? AND artifact_id=?")){q.setString(1,cut.account());q.setString(2,cut.artifactId());try(var r=q.executeQuery()){if(!r.next())return false;var rows=com.wheelwright.evidence.v2.FidelityPositions.csv(new String(r.getBytes(1),java.nio.charset.StandardCharsets.UTF_8));if(rows.isEmpty())return false;var header=rows.getFirst();int a=header.indexOf("Account number"),kind=header.indexOf("Investment type"),quantity=header.indexOf("Quantity");if(a<0||kind<0||quantity<0)return false;for(var row:rows)if(row.size()>Math.max(quantity,kind)&&row.get(a).strip().equals(cut.brokerAccount())&&!row.get(kind).strip().equals("Cash"))if(row.get(kind).isBlank()||com.wheelwright.evidence.v2.FidelityPositions.number(row.get(quantity).strip())==null)return false;return true;}}
 }
 private Set<String> scope(Connection tx,Document p)throws Exception{var result=new TreeSet<String>();for(var n:historicalLeaves(tx,p))result.add(n.at("/allocation/inventory/key").asText());result.remove("");return result;}
 private List<ObjectNode> historicalLeaves(Connection tx,Document p)throws Exception{return priorLeaves(repo,tx,p);}
 static List<ObjectNode> priorLeaves(PortfolioRepository repo,Connection tx,Document p)throws Exception{
  String uri=p.value().at("/currentConstruction/href").asText();var seen=new HashSet<String>();while(!uri.isBlank()&&seen.size()<2000&&seen.add(uri)){var c=repo.get(tx,uri);if(c.isEmpty()||!Objects.equals(c.get().account(),p.account())||!c.get().value().at("/position/href").asText().equals(p.uri()))break;var leaves=leaves(c.get().value().path("composition"));if(!leaves.isEmpty())return leaves;uri=c.get().value().at("/predecessor/href").asText();}return List.of();
 }
 private static ArrayNode evidence(Collection<ObjectNode> members){var es=array();for(var n:members)for(var e:n.at("/allocation/inventory/evidence"))es.add(e.deepCopy());return es;}
 static ObjectNode exposure(PositionSnapshot cut,String status,ArrayNode es,String qualification){if(es.isEmpty()&&cut.artifactId()!=null)es.add(source(cut.account(),cut.artifactId(),cut.observation()!=null?"/data/items":"1",cut.observation()!=null?null:cut.evidenceDate(),cut.recordedAt(),cut.observation()!=null?cut.observation().broker():"FIDELITY").put("requiredCapability","account.holdings.read:"+cut.account()));var n=obj().put("status",status).put("sourceSnapshotId",cut.snapshotId()).put("sourceDate",cut.evidenceDate()).put("receivedAt",cut.recordedAt()).put("continuity","UNRESOLVED").put("qualification",qualification);n.set("evidence",es);return n;}
 public static void qualifyEvaluation(ObjectNode position,Instant now){String status=position.at("/exposure/status").asText();if(!Set.of("UNKNOWN","RETAINED").contains(status))return;var e=(ObjectNode)position.path("evaluation");for(String key:List.of("marketValue","estimatedClosingCashFlow","grossUnrealizedPl","netUnrealizedPl","brokerReportedOpenPl","openingCashFlow","fees"))e.set(key,unknown("MONEY",now.toString(),"HOLDING_RECONCILIATION_CONFLICT"));e.remove("economicComparison");e.put("freshness","UNKNOWN").putNull("oldestMaterialObservationAt");var timeline=(ObjectNode)e.path("timeline");timeline.putNull("openedAt").put("openingAccess","UNKNOWN");timeline.set("openingEvidence",array());timeline.set("originalDays",unknown("DAY",now.toString(),"HOLDING_RECONCILIATION_CONFLICT"));var range=(ObjectNode)e.path("range");range.put("status","UNSUPPORTED").put("kind","UNAVAILABLE").putNull("lower").putNull("upper");range.set("evidence",array());range.set("warningCodes",array().add("HOLDING_RECONCILIATION_CONFLICT"));var payoff=(ObjectNode)e.path("payoff");payoff.put("status","UNSUPPORTED").putNull("geometry");payoff.set("evidence",array());payoff.set("warningCodes",array().add("HOLDING_RECONCILIATION_CONFLICT"));var management=(ObjectNode)e.path("management");management.put("associationStatus","UNAVAILABLE").putNull("manualCheckpoint");management.set("orders",array());management.set("evidence",array());for(String key:List.of("profitTargetGrossPl","reportedStopThresholdGrossPl"))management.set(key,unknown("MONEY",now.toString(),"HOLDING_RECONCILIATION_CONFLICT"));}
}
